std::vector<std::size_t> result;
if (k == 0 || points.empty()) {
    return result;
}
std::vector<std::pair<float_t, std::size_t>> distIdx;
distIdx.reserve(points.size());
for (std::size_t i = 0; i < points.size(); ++i) {
    const auto& pt = points[i];
    float_t dx = pt.x - searchPoint.x;
    float_t dy = pt.y - searchPoint.y;
    float_t dz = pt.z - searchPoint.z;
    float_t d2 = dx * dx + dy * dy + dz * dz;
    distIdx.emplace_back(d2, i);
}
std::size_t limit = std::min(k, points.size());
std::partial_sort(distIdx.begin(), distIdx.begin() + limit, distIdx.end(),
    [](const auto& a, const auto& b) { return a.first < b.first; });
result.reserve(limit);
for (std::size_t i = 0; i < limit; ++i) {
    result.push_back(distIdx[i].second);
}
return result;

